+async fn info(State(chains): State<Chains>, Path(hash): Path<String>) -> Response {
+    match chains.get(&hash) {
+        Some(chain) => Json(chain.info.clone()).into_response(),
+        None => StatusCode::NOT_FOUND.into_response(),
+    }
+}
